/**
 * TestimonialCard
 *
 * Dark card with a quote mark + word-by-word quote + horizontal divider
 * + author block (avatar + name + role). Card scales in, quote mark
 * pops, quote reveals word-by-word, divider expands, author rises in.
 *
 * This is the ONE implementation:
 * social-testimonial.tsx composes this component (background glow +
 * SceneBackground stay in the template), so template fixes reach
 * vibecoded scenes and vice versa.
 */

import * as React from "react";
import { interpolate, spring, SPRING_SMOOTH, SPRING_SNAPPY } from "../../react-animations/animation-utils";
import { autoTextColor } from "../../scene-templates/color-utils";
import { stripPipe } from "../../scene-templates/text-utils";
// `lighten` replaces the historical inlined `lightenHex` copy — for integer
// RGB channels round(v + x) ≡ v + round(x), so the two are bit-identical.
import { TOKEN_DEFAULTS, lighten } from "../../scene-templates/tokens";

const CLAMP = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

// ─── Typed component (direct use from templates) ────────────────

export interface TestimonialCardProps {
  /** Scene progress 0→1 */
  progress: number;
  /** The testimonial quote */
  quote: string;
  /** Author name (initial used in avatar) */
  authorName: string;
  /** Author role / title (optional, rendered as a smaller line below name) */
  authorRole?: string;
  /** Avatar background color. Defaults to "#ec4899". */
  avatarColor?: string;
  /** Accent color for the quote mark. Defaults to "#00e5a0". */
  accent?: string;
  /** Explicit brand-kit elevated surface for the card fill. Falls back to
   *  the tuned near-black card. */
  surfaceElevated?: string;
  /** Explicit brand-kit muted text color for the role line. */
  muted?: string;
  /** Frame width */
  width: number;
  /** Frame height */
  height: number;
  /** Beat pulse 0→1 */
  beatIntensity?: number;
}

export const TestimonialCard: React.FC<TestimonialCardProps> = ({
  progress,
  quote: rawQuote,
  authorName: rawAuthorName,
  authorRole: rawAuthorRole = "",
  avatarColor = "#ec4899",
  accent = TOKEN_DEFAULTS.accent,
  surfaceElevated,
  muted,
  width,
  height,
  beatIntensity = 0,
}) => {
  const dim = Math.min(width, height);
  const s = dim / 1080;

  const quote = stripPipe(rawQuote || "");
  const authorName = stripPipe(rawAuthorName || "");
  const authorRole = stripPipe(rawAuthorRole || "");
  const initialChar = authorName.charAt(0).toUpperCase();

  // Card colors — solid dark; explicit brand-kit values win when set
  const cardBg = surfaceElevated || lighten("#0a0a0f", 0.08);
  const borderColor = lighten("#0a0a0f", 0.15);
  const textPrimary = "#ffffff";
  const textSecondary = muted || "#94a3b8";

  // Quotation mark entrance
  const quoteMarkP = spring(interpolate(progress, [0.02, 0.2], [0, 1], CLAMP), SPRING_SNAPPY);
  const quoteMarkScale = interpolate(quoteMarkP, [0, 1], [0.3, 1]);
  const quoteMarkOpacity = quoteMarkP;

  // Horizontal divider expand
  const lineWidth = interpolate(progress, [0.35, 0.55], [0, 100], CLAMP);

  // Author entrance
  const authorP = spring(interpolate(progress, [0.45, 0.7], [0, 1], CLAMP), SPRING_SMOOTH);
  const authorY = interpolate(authorP, [0, 1], [20 * s, 0]);
  const authorOpacity = authorP;

  // Card dimensions
  const cardWidth = Math.min(width * 0.75, dim * 0.85);
  const cardPad = dim * 0.045;
  const avatarSize = dim * 0.055;

  // Card entrance
  const cardP = spring(interpolate(progress, [0, 0.15], [0, 1], CLAMP), SPRING_SMOOTH);
  const cardScale = interpolate(cardP, [0, 1], [0.92, 1]);
  const cardOpacity = interpolate(cardP, [0, 1], [0, 1]);

  const beatScale = 1 + beatIntensity * 0.01;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <div
        style={{
          width: cardWidth,
          padding: cardPad,
          backgroundColor: cardBg,
          borderRadius: dim * 0.02,
          border: `1px solid ${borderColor}`,
          boxShadow: `0 ${dim * 0.01}px ${dim * 0.04}px rgba(0,0,0,0.4)`,
          position: "relative",
          zIndex: 1,
          transform: `scale(${cardScale * beatScale})`,
          opacity: cardOpacity,
        }}
      >
        {/* Quotation mark */}
        <div
          style={{
            fontSize: dim * 0.08,
            lineHeight: 0.8,
            color: accent,
            fontWeight: 700,
            marginBottom: dim * 0.018,
            transform: `scale(${quoteMarkScale})`,
            opacity: quoteMarkOpacity,
            transformOrigin: "left top",
          }}
        >
          {"“"}
        </div>

        {/* Quote — word-by-word reveal */}
        <div
          style={{
            fontSize: dim * 0.038,
            lineHeight: 1.6,
            color: textPrimary,
            fontWeight: 500,
            marginBottom: dim * 0.032,
            display: "flex",
            flexWrap: "wrap",
            gap: `0 ${dim * 0.007}px`,
          }}
        >
          {quote.split(/\s+/).filter(Boolean).map((word, i, arr) => {
            const wStart = 0.20 + i * (0.30 / Math.max(arr.length, 1));
            const wEnd = Math.min(wStart + 0.08, 0.55);
            const wordOpacity = interpolate(progress, [wStart, wEnd], [0, 1], CLAMP);
            const wordY = interpolate(progress, [wStart, wEnd], [8 * s, 0], CLAMP);
            return (
              <span
                key={i}
                style={{
                  opacity: wordOpacity,
                  transform: `translateY(${wordY}px)`,
                  display: "inline-block",
                }}
              >
                {word}
              </span>
            );
          })}
        </div>

        {/* Horizontal divider */}
        <div style={{ display: "flex", justifyContent: "center", marginBottom: dim * 0.028 }}>
          <div style={{ height: 1, width: `${lineWidth}%`, backgroundColor: borderColor }} />
        </div>

        {/* Author section */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: dim * 0.016,
            opacity: authorOpacity,
            transform: `translateY(${authorY}px)`,
          }}
        >
          <div
            style={{
              width: avatarSize,
              height: avatarSize,
              borderRadius: "50%",
              backgroundColor: avatarColor,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              fontSize: avatarSize * 0.45,
              fontWeight: 700,
              color: autoTextColor(avatarColor),
              flexShrink: 0,
            }}
          >
            {initialChar}
          </div>
          <div>
            <div
              style={{
                fontSize: dim * 0.032,
                fontWeight: 600,
                color: textPrimary,
                marginBottom: dim * 0.003,
              }}
            >
              {authorName}
            </div>
            {authorRole && (
              <div style={{ fontSize: dim * 0.024, color: textSecondary }}>{authorRole}</div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * Color utilities for scene templates.
 *
 * Provides safe color manipulation that works with hex colors
 * and graceful fallbacks for non-hex inputs.
 */
import React from "react";
import type { GlobalStyle } from "../video-config";
import { resolveTokens, darken } from "./tokens";
import type { BackgroundFamily } from "./tokens";

// ─── Layout constants ───────────────────────────────────────
//
// Shared vertical layout for templates that place a TextOverlay at the top of
// the scene (showcase-*, chart-*, infographic-*). Using a single constant
// guarantees the headline sits in the same place across every template, so
// scene-to-scene cuts don't visually jump.
//
// TextOverlay vertically centers itself inside its container, so the visual
// midline of the headline = TOP_TEXT_AREA_RATIO / 2 of the scene height.
export const TOP_TEXT_AREA_RATIO = 0.32;

/**
 * Convert a hex color + opacity (0-1) to an rgba() string.
 * Handles 3-digit (#abc) and 6-digit (#aabbcc) hex.
 * Falls back to the raw color with opacity if not parseable as hex.
 */
export function withOpacity(hex: string, opacity: number): string {
  const match = hex.match(/^#([0-9a-f]{3,8})$/i);
  if (!match) return hex; // Not hex — return as-is

  let r: number, g: number, b: number;
  const h = match[1];

  if (h.length === 3) {
    r = parseInt(h[0] + h[0], 16);
    g = parseInt(h[1] + h[1], 16);
    b = parseInt(h[2] + h[2], 16);
  } else if (h.length >= 6) {
    r = parseInt(h.slice(0, 2), 16);
    g = parseInt(h.slice(2, 4), 16);
    b = parseInt(h.slice(4, 6), 16);
  } else {
    return hex;
  }

  return `rgba(${r},${g},${b},${opacity})`;
}

/**
 * Check if a hex color is dark (luminance < 0.5).
 * Uses relative luminance formula from WCAG.
 */
export function isColorDark(hex: string): boolean {
  const match = hex.match(/^#([0-9a-f]{3,8})$/i);
  if (!match) return true; // Default to dark if not parseable

  let r: number, g: number, b: number;
  const h = match[1];

  if (h.length === 3) {
    r = parseInt(h[0] + h[0], 16);
    g = parseInt(h[1] + h[1], 16);
    b = parseInt(h[2] + h[2], 16);
  } else if (h.length >= 6) {
    r = parseInt(h.slice(0, 2), 16);
    g = parseInt(h.slice(2, 4), 16);
    b = parseInt(h.slice(4, 6), 16);
  } else {
    return true;
  }

  // Relative luminance (simplified sRGB)
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance < 0.5;
}

/**
 * Given two colors, return them ordered [darker, lighter] by relative
 * luminance. Used by gradient backgrounds so the darker stop always anchors
 * the top of the frame.
 */
export function orderDarkToLight(a: string, b: string): [string, string] {
  const lum = (hex: string): number => {
    const m = hex.match(/^#([0-9a-f]{6})$/i);
    if (!m) return 0;
    const h = m[1];
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b2 = parseInt(h.slice(4, 6), 16);
    return 0.299 * r + 0.587 * g + 0.114 * b2;
  };
  return lum(a) <= lum(b) ? [a, b] : [b, a];
}

/**
 * Auto-derive text color from background color.
 * Returns white for dark backgrounds, near-black for light ones.
 */
export function autoTextColor(bg: string): string {
  return isColorDark(bg) ? "#ffffff" : "#111111";
}

/**
 * Shift a hex color's hue by a number of degrees — canonical implementation
 * lives with the token resolver; re-exported here because every template
 * historically imports it from color-utils.
 */
export { shiftHue } from "./tokens";

/**
 * Gradient background — clean 2-color linear gradient with a subtle
 * animated breathing overlay. Matches the look of a plain CSS
 * `linear-gradient(90deg, colorA, colorB)` so palette chips preview
 * exactly what templates render.
 *
 * The animation is deliberately minimal: two low-opacity radial blobs
 * of the same two colors drift slowly, adding just enough motion for
 * video without introducing a third "midtone" color that muddies
 * the gradient (a common source of unwanted purple/brown tints).
 */
export function gradientBackground({
  colorA,
  colorB,
  solidBg,
  progress,
  sceneDuration,
  seed,
  family,
}: {
  colorA: string;
  colorB: string;
  /**
   * When set, the function returns this color as a solid background
   * (no gradient, no animated radial overlays). Used when the user has
   * a scraped brand whose darkest color reads as a real surface — the
   * accent stays on text/CTAs, but the bg goes flat instead of pairing
   * with an unrelated brand color and producing a noisy gradient.
   */
  solidBg?: string;
  progress: number;
  sceneDuration?: number;
  seed: number;
  /**
   * Background family from the style preset. Omitted = "mesh", the original
   * look — so existing configs are untouched. All families are pure CSS
   * background strings (no `filter`, which the SVG export can't rasterize)
   * and stay deterministic in `progress`.
   */
  family?: BackgroundFamily;
}): string {
  if (solidBg) return solidBg;
  const elapsed = progress * (sceneDuration || 3);
  const t = elapsed * 0.6;

  const seededRandom = (s: number): number => {
    const x = Math.sin(s * 12.9898 + s * 78.233) * 43758.5453;
    return x - Math.floor(x);
  };
  const phase = seededRandom(seed) * Math.PI * 2;

  // Darker of the two colors anchors the top of the frame so text and logos
  // sit over the stronger value. 180deg = top→bottom.
  const [topColor, bottomColor] = orderDarkToLight(colorA, colorB);

  if (family === "wash") {
    // No radials: one calm vertical ramp that drifts a few percent over the
    // scene. Reads considered rather than energetic.
    const shift = Math.sin(t * 0.5 + phase) * 6;
    return `linear-gradient(${175 + shift}deg, ${topColor} 0%, ${bottomColor} 100%)`;
  }

  if (family === "spotlight") {
    // A single hard pool of accent high in the frame over a near-black
    // surround — high contrast, very little colour area.
    const x = 50 + Math.sin(t * 0.4 + phase) * 8;
    const y = 28 + Math.cos(t * 0.3 + phase) * 5;
    return `
      radial-gradient(ellipse 70% 55% at ${x}% ${y}%, ${colorA}66 0%, ${colorA}1a 45%, transparent 72%),
      linear-gradient(180deg, ${darken(topColor, 0.55)} 0%, ${darken(bottomColor, 0.7)} 100%)
    `;
  }

  const x1 = 25 + Math.sin(t + phase) * 25;
  const y1 = 30 + Math.cos(t * 0.7 + phase + 1.0) * 25;
  const x2 = 75 + Math.sin(t * 0.6 + phase + 2.0) * 25;
  const y2 = 70 + Math.cos(t * 0.4 + phase + 3.5) * 25;

  return `
    radial-gradient(ellipse 60% 60% at ${x1}% ${y1}%, ${colorA}4d 0%, transparent 65%),
    radial-gradient(ellipse 60% 60% at ${x2}% ${y2}%, ${colorB}4d 0%, transparent 65%),
    linear-gradient(180deg, ${topColor} 0%, ${bottomColor} 100%)
  `;
}

/**
 * Animated brand-gradient overlay. Drop as the first child inside a template's
 * outer container. Uses accent + secondary (or hue-shifted accent) as gradient
 * colors. When the user is in solid mode (accent = secondary = bg), the
 * gradient collapses to a flat layer — no visual effect beyond the solid bg.
 */
export const BrandGradientOverlay: React.FC<{
  style: GlobalStyle;
  progress: number;
  sceneDuration?: number;
  seed: number;
}> = ({ style: globalStyle, progress, sceneDuration, seed }) => {
  const tokens = resolveTokens(globalStyle);
  const accent = tokens.accent;
  // tokens.secondary carries the "auto" guard: an explicit kit secondary
  // passes through verbatim, but the literal string "auto" (the kit's
  // derive-for-me sentinel) resolves to shiftHue(accent, 50) instead of
  // leaking into the CSS gradient as an invalid color.
  const secondary = tokens.secondary;
  const solidBg = tokens.bg;

  return React.createElement("div", {
    style: {
      position: "absolute" as const,
      inset: 0,
      background: gradientBackground({ colorA: accent, colorB: secondary, solidBg, progress, sceneDuration, seed, family: tokens.preset.background }),
      pointerEvents: "none" as const,
    },
  });
};

/**
 * VideoConfig — React template-based architecture.
 *
 * Every scene is a React template. Templates declare their variables via a schema,
 * and the Studio auto-generates input UI from it. AI picks templates by matching
 * descriptions to the user's prompt.
 */

// ─── Orientation & Dimensions ──────────────────────────────────

export type Orientation = "portrait" | "landscape";

export interface VideoDimensions {
  width: number;
  height: number;
  aspectRatio: string;
}

export interface SafeZone {
  top: number;
  bottom: number;
  left: number;
  right: number;
}

export function getDimensions(orientation: Orientation = "portrait"): VideoDimensions {
  return orientation === "landscape"
    ? { width: 1920, height: 1080, aspectRatio: "16 / 9" }
    : { width: 1080, height: 1920, aspectRatio: "9 / 16" };
}

export function getSafeZone(orientation: Orientation = "portrait"): SafeZone {
  return orientation === "landscape"
    ? { top: 108, bottom: 108, left: 192, right: 192 }    // SMPTE broadcast safe (10%)
    : { top: 100, bottom: 100, left: 60, right: 60 };     // Balanced safe zone — enough margin without eating content
}

// ─── Core Config ───────────────────────────────────────────────

export interface VideoConfig {
  orientation?: Orientation;
  audio?: AudioConfig;
  scenes: SceneConfig[];
  style: GlobalStyle;
  meta?: VideoMeta;
}

// ─── Audio ─────────────────────────────────────────────────────

export interface AudioConfig {
  trackId: string;
  audioUrl: string;
  duration: number;
  beatDetection: BeatDetectionConfig;
  beatMarkers: BeatMarker[];
  /** Volume 0.0-1.0. Default 1.0 (full track volume). */
  volume?: number;
  /** Fade-out duration in milliseconds at end of audio. When unset, falls
   *  back to min(lastSceneDuration, 3s) via `defaultFadeOutMs()` — the fade
   *  ramps down over the closer instead of cutting hard. Set explicitly
   *  (including 0) to override. */
  fadeOutMs?: number;
}

export interface BeatDetectionConfig {
  sensitivity: number;
  targetBeats?: number;
  minInterval?: number;
}

export interface BeatMarker {
  time: number;
  manual?: boolean;
  energy?: "high" | "medium" | "low";
}

// ─── Scene ─────────────────────────────────────────────────────

export interface SceneConfig {
  id: string;
  templateId: string;
  variables: Record<string, unknown>;
  /** Text archetype for this scene. One of the 6 names in TEXT_ARCHETYPES. */
  textArchetype?: string;
  // Note: scene-level transition override (formerly `transition?: string` with
  // a UI selector for crossfade / cut / slide / flash / dip / zoom) was
  // removed when none of the eight options were wired to the renderer.
  // Renderer now picks cut vs dissolve from `shouldDissolveBetween` in
  // scene-resolver.ts. Re-introduce as `transition: "cut" | "dissolve"` here
  // if real exceptions to the continuity rule appear.
  /** Override video-level default background effect (for templates that opt in) */
  backgroundEffect?: string;
  /**
   * Per-scene background override. When set, this scene renders on the
   * overridden gradient (accent + secondary) instead of the video-level
   * brand. Solid mode = accent equals secondary; gradient = distinct.
   */
  backgroundOverride?: { accent: string; secondary: string };
  timing: TimingConfig;
  /** AI-generated alternative templates with purpose-written copy. 0–3 per scene. */
  alternatives?: AlternativeTemplate[];
  /**
   * Raw React source for vibecoded (custom_*) templates. Set on save so
   * server-side render (`/render` + Trigger.dev export) can rehydrate the
   * template without the client's sessionStorage. Empty for built-in
   * templates. Stripped before display — never read at runtime in the Studio
   * (the in-memory `customTemplates` registry is the source of truth there).
   */
  componentSource?: string;
  /**
   * Where an ejected scene came from. Without it a `custom_*` scene is an
   * anonymous blob: nothing records which registry item it started as or
   * which version, so when the upstream item changes — a safe-zone fix, an
   * export constraint, a bug — there is no way to tell the owner their copy
   * is behind, and no way to show them what changed.
   *
   * Set on eject. `vanillasky diff` compares `originHash` against the current
   * registry item; a mismatch means upstream moved since you ejected.
   */
  origin?: SceneOrigin;
}

/** Provenance for an ejected (`custom_*`) scene. */
export interface SceneOrigin {
  /** Registry item this was ejected from, e.g. "bigNumber" or "countUpNumber". */
  item: string;
  /** Registry version at eject time. */
  version?: string;
  /** Hash of the upstream source at eject time — the thing diff compares. */
  sourceHash?: string;
  /** ISO date, for "you ejected this 6 months ago" context. */
  ejectedAt?: string;
}

// ─── Alternative Template ─────────────────────────────────────

export interface AlternativeTemplate {
  templateId: string;
  variables: Record<string, unknown>;
  /** Human-readable rationale shown in the picker (e.g. "More cinematic", "Social proof angle") */
  rationale?: string;
}

// ─── Variable Schema ──────────────────────────────────────────

export interface VariableField {
  type: "string" | "number" | "boolean" | "enum" | "media" | "color" | "data-points";
  label: string;
  default?: unknown;
  /** Options for enum type */
  options?: string[];
  required?: boolean;
  /** Help text shown in Studio and used by AI for context */
  description?: string;
}

// ─── Timing ────────────────────────────────────────────────────

export interface TimingConfig {
  beatStart?: number;           // beat marker index (beat-sync mode)
  beatEnd?: number;             // beat marker index (beat-sync mode)
  startTime?: number;           // seconds (time-based mode)
  endTime?: number;             // seconds (time-based mode)
  fixedDuration?: number;       // seconds (no-audio mode)
  durationWeight?: number;      // relative weight for auto-distribution
}

// ─── Style ─────────────────────────────────────────────────────

export interface GlobalStyle {
  font: string;
  brandKit?: BrandKit;
  /**
   * Named style preset — the frame-level look (background family, title type
   * treatment, title placement). One token that moves several decisions
   * coherently, so two videos with the same brand colors don't come out
   * looking identical. Resolved in scene-templates/tokens.ts; unset or
   * unknown falls back to the default preset, which reproduces the original
   * look exactly. See STYLE_PRESETS for the list.
   */
  preset?: string;
  /** Default text archetype when a scene doesn't set one. */
  defaultTextArchetype?: string;
  /** Default transition between scenes */
  defaultTransition?: string;
  /** Default background effect — consumed by templates with usesGlobalBackgroundEffect: true */
  defaultBackgroundEffect?: string;
}

// ─── Brand Kit ────────────────────────────────────────────────

export interface BrandKit {
  /** Primary brand color — drives one half of the gradient mesh and most accents. */
  accent: string;
  /** Secondary brand color — drives the other half of the gradient mesh.
   *  When equal to accent, the gradient collapses to a flat color (solid mode). */
  secondary?: string;
  /** Optional explicit text color override — defaults to white (#ffffff) when
   *  not set. Templates render scrims/vignettes to handle bright surfaces. */
  text?: string;
  logoDataUrl?: string;
  /**
   * Solid scene background override. When set, the gradient renderer
   * collapses to this single color — use it when the brand has a clear dark
   * surface (e.g., dark body text on a light marketing page reads as a real
   * navy / charcoal brand color). Pairing it with `accent` in a gradient
   * produces muddy results, so anchor the bg flat and let `accent` handle
   * highlights.
   */
  bg?: string;
  /**
   * Normalized URL the brand kit was derived from, when it came from a URL
   * rather than being set explicitly. Acts as a cache key: a later config
   * pointing at the same URL can reuse the kit instead of re-deriving it.
   */
  sourceUrl?: string;

  // ─── Extended fields for primitive composition ────────────────────
  /** Deepest background surface — defaults to a near-black if unset. */
  surface?: string;
  /** Elevated card / panel surface — defaults to surface + 4% lighten. */
  surface_elevated?: string;
  /** Muted text color for labels, footers, supporting copy. Default #a7a6b0. */
  muted?: string;
  /** Script accent font family for handwritten callouts (Caveat-style). Default "Caveat". */
  script_font?: string;
  /** Inferred mood/vibe from URL capture — used downstream for music selection. */
  vibe?: "default" | "reflective" | "edgy" | "playful" | "premium";
}

// ─── Gradient / Background Style (used by VideoManager, VideoCardPreview, BackgroundShowcase for saved videos) ──

export type BackgroundStyle = "solid" | "blobs" | "waves" | "blurry-gradient" | "circles" | "blob-scene" | "layered-waves" | "stacked-waves" | "blob-scatter" | "polygon-scatter" | "symbol-scatter" | "radial-gradient" | "mesh-gradient" | (string & {});

export interface PatternParams {
  complexity?: number;
  contrast?: number;
  size?: number;
  count?: number;
  balance?: number;
  variant?: "solid" | "outline";
  direction?: "up" | "down" | "left" | "right";
}

export interface GradientConfig {
  colors: [string, string];
  style: BackgroundStyle;
  animationSpeed: number;
  params?: PatternParams;
}

// ─── Meta ──────────────────────────────────────────────────────

export interface VideoMeta {
  name?: string;
  prompt?: string;
  sourceUrl?: string;
  createdAt?: string;
  mood?: string[];
  videoType?: string;
  /** Video format. Currently only "launch"; grows as new formats ship (review, milestone, etc.). */
  format?: "launch";
  trackRationale?: string;
  templateRationale?: string;
  source?: string;
  uploadedMediaUrls?: string[];
  /** Flat list of images the user uploaded on the landing page. The chat
   *  routes them to scenes via vision + setSceneMedia on turn 0. */
  uploadedImages?: string[];
  documentContent?: string;
  /** Stable identifier for the studio chat thread tied to this config.
   *  Lazily assigned the first time the user opens the chat, persisted via
   *  the same localStorage path as the rest of the config so the chat
   *  history (kept in sessionStorage under this key) can be rehydrated
   *  across tab switches and page reloads within a session. */
  chatId?: string;
  /** The `shared_configs` row this video is persisted to. Stamped when a
   *  config loads from `?config=<id>` and on the first autosave/export of a
   *  new build. Anchors continuous autosave + export to a single row
   *  (update-in-place) instead of minting a new row per save. */
  savedConfigId?: string;
  /** Stamped server-side by save-config when markExported is passed. */
  exported_at?: string;
}

/**
 * The declared format, from either place it can live.
 *
 * The CLI and the skill write `"format": "launch"` at the top level (that's
 * what `vanillasky validate` reads), while the web app stores it under
 * `meta.format`. A config written by an agent therefore looks format-less to
 * the app — which quietly changed how the music picker filtered. Read both
 * until the two conventions are reconciled.
 */
export function resolveFormat(config: VideoConfig): VideoMeta["format"] | undefined {
  const top = (config as VideoConfig & { format?: VideoMeta["format"] }).format;
  return config.meta?.format ?? top;
}

// ─── Validation ────────────────────────────────────────────────

export function validateVideoConfig(config: unknown): config is VideoConfig {
  if (!config || typeof config !== "object") return false;
  const c = config as Record<string, unknown>;

  if (!Array.isArray(c.scenes) || c.scenes.length === 0) return false;
  if (!c.style || typeof c.style !== "object") return false;

  const style = c.style as Record<string, unknown>;
  if (typeof style.font !== "string") return false;

  for (const scene of c.scenes as Record<string, unknown>[]) {
    if (!scene.id || typeof scene.id !== "string") return false;
    if (!scene.templateId || typeof scene.templateId !== "string") return false;
    if (!scene.timing || typeof scene.timing !== "object") return false;
  }

  // Validate audio if present
  if (c.audio) {
    const audio = c.audio as Record<string, unknown>;
    if (typeof audio.trackId !== "string") return false;
    if (typeof audio.audioUrl !== "string") return false;
    if (typeof audio.duration !== "number") return false;
    if (!Array.isArray(audio.beatMarkers)) return false;
    if (!audio.beatDetection || typeof audio.beatDetection !== "object") return false;
  }

  return true;
}

// ─── Factory ───────────────────────────────────────────────────

export function createDefaultScene(overrides?: Partial<SceneConfig>): SceneConfig {
  return {
    id: crypto.randomUUID(),
    templateId: "media",
    variables: {
      texts: "",
      mediaUrl: "",
      mediaKeyword: "",
    },
    timing: { fixedDuration: 3 },
    ...overrides,
  };
}
